import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ParameterLibraryService } from '../../services/parameter-library.service';
import { ParameterType, ParameterInputType, SelectOption, DateTimePreset } from '../../models/parameter-library.model';
import { HelpModal } from '../../components/help-modal/help-modal';

@Component({
  selector: 'app-parameter-manager',
  standalone: true,
  imports: [FormsModule, HelpModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './parameter-manager.html',
  styleUrl: './parameter-manager.scss'
})
export class ParameterManager {
  readonly paramLibrary = inject(ParameterLibraryService);

  /** Currently selected parameter type key */
  selectedTypeKey = signal<string | null>(null);

  /** Whether we're in "add new" mode */
  addingNew = signal(false);

  /** Whether the help modal is open */
  helpOpen = signal(false);

  /** New parameter type form data */
  newType = signal<Partial<ParameterType>>({
    key: '',
    label: '',
    inputType: 'text',
    description: ''
  });

  /** Tracks field-level overrides when editing a built-in type */
  editOverrides = signal<Partial<ParameterType>>({});

  /** The resolved ParameterType for the current selection */
  readonly selectedType = computed(() => {
    const key = this.selectedTypeKey();
    return key ? this.paramLibrary.getType(key) : undefined;
  });

  /** Whether the selected type is built-in */
  readonly isSelectedBuiltIn = computed(() => {
    const key = this.selectedTypeKey();
    return key ? this.paramLibrary.isBuiltIn(key) : false;
  });

  /** Whether the selected built-in type has an active override */
  readonly hasOverride = computed(() => {
    const key = this.selectedTypeKey();
    return key ? this.paramLibrary.getBuiltInOverride(key) !== undefined : false;
  });

  /** Available input types for the dropdown */
  readonly inputTypes: { label: string; value: ParameterInputType }[] = [
    { label: 'Text', value: 'text' },
    { label: 'Number', value: 'number' },
    { label: 'Select (Dropdown)', value: 'select' },
    { label: 'Date/Time', value: 'datetime' },
    { label: 'Date', value: 'date' },
    { label: 'Time', value: 'time' },
    { label: 'Hidden', value: 'hidden' }
  ];

  selectType(key: string): void {
    this.selectedTypeKey.set(key);
    this.addingNew.set(false);
    const override = this.paramLibrary.getBuiltInOverride(key);
    this.editOverrides.set(override ? { ...override } : {});
  }

  startAddNew(): void {
    this.addingNew.set(true);
    this.selectedTypeKey.set(null);
    this.newType.set({
      key: '',
      label: '',
      inputType: 'text',
      description: ''
    });
  }

  cancelAddNew(): void {
    this.addingNew.set(false);
  }

  updateNewTypeField(field: string, value: any): void {
    this.newType.update(t => ({ ...t, [field]: value }));
  }

  /** Auto-generate a key from the label */
  autoGenerateKey(): void {
    const label = this.newType().label || '';
    const key = label.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
    this.newType.update(t => ({ ...t, key }));
  }

  /** Check if a key is unique across all parameter types */
  isKeyUnique(key: string): boolean {
    return !this.paramLibrary.allTypes().some(t => t.key === key);
  }

  saveNewType(): void {
    const t = this.newType();
    if (!t.key || !t.label) return;
    if (!this.isKeyUnique(t.key!)) return;

    const paramType: ParameterType = {
      key: t.key!,
      label: t.label!,
      inputType: t.inputType as ParameterInputType || 'text',
      description: t.description || '',
      defaultValue: t.defaultValue,
      placeholder: t.placeholder,
      allowEmpty: t.allowEmpty,
      unquoted: t.unquoted,
      options: t.options,
      presets: t.presets,
      cclFormat: t.cclFormat
    };

    this.paramLibrary.addCustomType(paramType);
    this.addingNew.set(false);
    this.selectedTypeKey.set(paramType.key);
  }

  /** Update a field override for a built-in type */
  updateBuiltInOverride(field: string, value: any): void {
    this.editOverrides.update(o => ({ ...o, [field]: value }));
    this.paramLibrary.setBuiltInOverride(this.selectedTypeKey()!, this.editOverrides());
  }

  /** Reset all overrides for the selected built-in type */
  resetBuiltInOverride(): void {
    this.paramLibrary.clearBuiltInOverride(this.selectedTypeKey()!);
    this.editOverrides.set({});
  }

  /** Remove a custom parameter type */
  removeType(key: string): void {
    this.paramLibrary.removeCustomType(key);
    if (this.selectedTypeKey() === key) {
      this.selectedTypeKey.set(null);
    }
  }

  /** Update a custom type field and persist */
  updateCustomField(field: string, value: any): void {
    const key = this.selectedTypeKey();
    if (!key) return;
    this.paramLibrary.updateCustomType(key, { [field]: value });
  }

  // --- Options management for select types ---

  addOption(): void {
    const t = this.newType();
    const options = [...(t.options || []), { label: '', value: '' }];
    this.newType.update(n => ({ ...n, options }));
  }

  removeOption(index: number): void {
    const options = [...(this.newType().options || [])];
    options.splice(index, 1);
    this.newType.update(n => ({ ...n, options }));
  }

  updateOption(index: number, field: 'label' | 'value', value: string): void {
    const options = [...(this.newType().options || [])];
    options[index] = { ...options[index], [field]: value };
    this.newType.update(n => ({ ...n, options }));
  }

  // --- Options management for existing custom types ---

  addCustomOption(): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const options = [...(type.options || []), { label: '', value: '' }];
    this.paramLibrary.updateCustomType(key, { options });
  }

  removeCustomOption(index: number): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const options = [...(type.options || [])];
    options.splice(index, 1);
    this.paramLibrary.updateCustomType(key, { options });
  }

  updateCustomOption(index: number, field: 'label' | 'value', value: string): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const options = [...(type.options || [])];
    options[index] = { ...options[index], [field]: value };
    this.paramLibrary.updateCustomType(key, { options });
  }

  // --- Presets management for datetime types ---

  addPreset(): void {
    const t = this.newType();
    const presets = [...(t.presets || []), { label: '', preset: '' }];
    this.newType.update(n => ({ ...n, presets }));
  }

  removePreset(index: number): void {
    const presets = [...(this.newType().presets || [])];
    presets.splice(index, 1);
    this.newType.update(n => ({ ...n, presets }));
  }

  updatePreset(index: number, field: 'label' | 'preset', value: string): void {
    const presets = [...(this.newType().presets || [])];
    presets[index] = { ...presets[index], [field]: value };
    this.newType.update(n => ({ ...n, presets }));
  }

  // --- Presets management for existing custom types ---

  addCustomPreset(): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const presets = [...(type.presets || []), { label: '', preset: '' }];
    this.paramLibrary.updateCustomType(key, { presets });
  }

  removeCustomPreset(index: number): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const presets = [...(type.presets || [])];
    presets.splice(index, 1);
    this.paramLibrary.updateCustomType(key, { presets });
  }

  updateCustomPreset(index: number, field: 'label' | 'preset', value: string): void {
    const key = this.selectedTypeKey();
    const type = this.selectedType();
    if (!key || !type) return;
    const presets = [...(type.presets || [])];
    presets[index] = { ...presets[index], [field]: value };
    this.paramLibrary.updateCustomType(key, { presets });
  }
}
